import ExoNitCore
import Foundation

// Contract tests for the epoch-class harmonic resolver port (flag `harmonic_epoch_class`).
// Goldens: Fixtures/epoch_class/epoch_class_golden.json, generated by the Python
// implementation with Fixtures/epoch_class/generate_epoch_class_golden.py. All float64 values
// are stored as IEEE-754 bit patterns, so every comparison below is BIT-EXACT (a NaN matches
// any NaN); there is deliberately no tolerance.

private struct EpochFixture: Decodable {
    struct Prep: Decodable {
        let ep0: Int
        let n_e: [UInt64]
        let d_e: [UInt64]
        let covered: [Bool]
        let sigma: UInt64
        let period: UInt64
        let centre: UInt64
    }
    struct Stats: Decodable {
        let depth: [UInt64]
        let err: [UInt64]
        let nep: [Int]
        let ndip: [Int]
    }
    struct Eph: Decodable {
        let period: UInt64
        let t0: UInt64
        let duration: UInt64
        let centre: Bool
        let use_excluded: Bool
        let prep: Prep?
        let transit_centre: UInt64
        let stats: [String: Stats]
        let parity: [String: String]
        let demotion: [String: Bool]
        let guard_genuine: [String: Bool]
        let demotion_v0: [String: Bool]
        let demotion_v1: [String: Bool]
        let ks: [Int]
        let ks_short_max: [Int]
        let period_max_short: UInt64
    }
    struct Ephemeris: Decodable {
        let period: UInt64
        let t0: UInt64
        let duration: UInt64
    }
    struct Slot: Decodable {
        let rm: Ephemeris
        let accepted: [Ephemeris]
        let centre: Bool
        let match: Int
        let drop: Bool
    }
    struct Result: Decodable {
        let period: UInt64
        let snr: UInt64
        let depth: UInt64
        let duration: UInt64
        let t0: UInt64
    }
    struct Row: Decodable {
        let period: UInt64
        let snr: UInt64
        let depth: UInt64
        let duration: UInt64
        let t0: UInt64
    }
    struct Promote: Decodable {
        let seed: Result
        let period_max: UInt64
        let snr_min: UInt64
        let table: [Row]
        let use_excluded: Bool
        let promoted: Bool
        let result: Result
        let calls: [[UInt64]]
    }
    struct Resolve: Decodable {
        let seed: Result
        let period_min: UInt64
        let period_max: UInt64
        let source: String
        let epoch_class: Bool
        let use_excluded: Bool
        let table: [Row]
        let result: Result
        let calls: [[UInt64]]
        let name: String?
    }
    struct Case: Decodable {
        let name: String
        let time: [UInt64]
        let flux: [UInt64]
        let excluded: [Int]?
        let ephemerides: [Eph]
        let slots: [Slot]
        let promotes: [Promote]
        let resolves: [Resolve]
    }
    let flag_off_n: Int
    let flag_off: [Resolve]
    let cases: [Case]
}

private func dbl(_ bits: UInt64) -> Double { Double(bitPattern: bits) }
private func dbls(_ bits: [UInt64]) -> [Double] { bits.map(Double.init(bitPattern:)) }

/// Bit-exact equality; any NaN equals any NaN (numpy and Swift may differ in NaN payload/sign).
private func same(_ a: Double, _ bits: UInt64) -> Bool {
    let b = Double(bitPattern: bits)
    if a.isNaN && b.isNaN { return true }
    return a.bitPattern == bits
}

private func sameArray(_ a: [Double], _ bits: [UInt64]) -> Bool {
    a.count == bits.count && zip(a, bits).allSatisfy { same($0, $1) }
}

private func loadEpochFixture() throws -> EpochFixture {
    let root = URL(fileURLWithPath: #filePath).deletingLastPathComponent()
        .deletingLastPathComponent().deletingLastPathComponent()
    return try JSONDecoder().decode(
        EpochFixture.self,
        from: Data(contentsOf: root.appendingPathComponent(
            "Fixtures/epoch_class/epoch_class_golden.json"))
    )
}

private final class CallLog: @unchecked Sendable {
    var calls: [[UInt64]] = []
}

/// Same canned BLS as the Python generator: first table row whose period is within 5 % of
/// the window centre, else a null (snr 0) result. Logs every call (lo, hi, n) as bit patterns.
private func mockSearch(_ table: [EpochFixture.Row], _ log: CallLog) -> BLSSearchFunction {
    return { _, _, parameters in
        log.calls.append([
            parameters.periodMinimum.bitPattern, parameters.periodMaximum.bitPattern,
            UInt64(parameters.periodCount),
        ])
        let c = 0.5 * (parameters.periodMinimum + parameters.periodMaximum)
        for row in table {
            let p = dbl(row.period)
            if abs(c - p) / p < 0.05 {
                let depth = dbl(row.depth)
                return BLSResult(
                    period: p, power: 1.0, duration: dbl(row.duration), t0: dbl(row.t0),
                    depth: depth, depthPPM: depth * 1e6, snr: dbl(row.snr),
                    periods: [], powerSpectrum: []
                )
            }
        }
        return BLSResult(
            period: c, power: 0, duration: 0.1, t0: 0, depth: 0, depthPPM: 0, snr: 0,
            periods: [], powerSpectrum: []
        )
    }
}

private func blsSeed(_ r: EpochFixture.Result) -> BLSResult {
    let depth = dbl(r.depth)
    return BLSResult(
        period: dbl(r.period), power: 1.0, duration: dbl(r.duration), t0: dbl(r.t0),
        depth: depth, depthPPM: depth * 1e6, snr: dbl(r.snr),
        periods: [], powerSpectrum: []
    )
}

private func sameResult(_ r: BLSResult, _ g: EpochFixture.Result) -> Bool {
    same(r.period, g.period) && same(r.snr, g.snr) && same(r.depth, g.depth)
        && same(r.duration, g.duration) && same(r.t0, g.t0)
}

private func source(_ name: String) -> LightCurveSource { name == "ffi" ? .ffi : .spoc }

func testEpochClassPythonGoldenParity() async throws {
    let fixture = try loadEpochFixture()
    try expect(fixture.cases.count == 13, "golden must contain the 13 synthetic cases")
    for c in fixture.cases {
        let time = dbls(c.time), flux = dbls(c.flux)
        let excluded: [Bool]? = c.excluded.map { $0.map { $0 != 0 } }
        for (n, e) in c.ephemerides.enumerated() {
            let tag = "\(c.name) eph#\(n)"
            let period = dbl(e.period), t0 = dbl(e.t0), duration = dbl(e.duration)
            let ex = e.use_excluded ? excluded : nil
            try expect(
                same(HarmonicEpochClass.transitCentre(t0, duration, e.centre), e.transit_centre),
                "\(tag) transit centre"
            )
            let prep = HarmonicEpochClass.prepareEpochs(
                time: time, flux: flux, period: period, t0: t0, duration: duration,
                excluded: ex, t0IsCentre: e.centre
            )
            if let g = e.prep {
                guard let p = prep else { throw TestFailure(description: "\(tag) prep nil") }
                try expect(p.ep0 == g.ep0, "\(tag) ep0 \(p.ep0) != \(g.ep0)")
                try expect(sameArray(p.nE, g.n_e), "\(tag) n_e")
                try expect(sameArray(p.dE, g.d_e), "\(tag) d_e")
                try expect(p.covered == g.covered, "\(tag) covered")
                try expect(same(p.sigma, g.sigma), "\(tag) sigma")
                try expect(same(p.period, g.period), "\(tag) refined period \(p.period)")
                try expect(same(p.centre, g.centre), "\(tag) refined centre")
            } else {
                try expect(prep == nil, "\(tag) prep must be nil")
            }
            for k in 2...5 {
                let s = HarmonicEpochClass.classStats(prep, k: k)
                guard let g = e.stats[String(k)] else {
                    throw TestFailure(description: "\(tag) missing stats k=\(k)")
                }
                try expect(sameArray(s.depth, g.depth), "\(tag) k=\(k) depth")
                try expect(sameArray(s.err, g.err), "\(tag) k=\(k) err")
                try expect(s.nep == g.nep, "\(tag) k=\(k) nep")
                try expect(s.ndip == g.ndip, "\(tag) k=\(k) ndip")
                let parity = HarmonicEpochClass.harmonicParity(
                    time: time, flux: flux, period: period, t0: t0, duration: duration,
                    k: k, excluded: ex, t0IsCentre: e.centre
                )
                try expect(parity.rawValue == e.parity[String(k)], "\(tag) k=\(k) parity")
                if !e.centre {
                    let sub = BLSResult(
                        period: period, power: 0, duration: duration, t0: t0, depth: 0,
                        depthPPM: 0, snr: 0, periods: [], powerSpectrum: []
                    )
                    let supported = HarmonicEpochClass.demotionSupported(
                        time: time, flux: flux, sub: sub, k: k, excluded: ex
                    )
                    try expect(supported == e.demotion[String(k)], "\(tag) k=\(k) demotion")
                    let genuine = HarmonicEpochClass.shortPeriodGenuine(
                        time: time, flux: flux, sub: sub, k: k, excluded: ex
                    )
                    try expect(genuine == e.guard_genuine[String(k)], "\(tag) k=\(k) G1 guard")
                    if c.name.hasPrefix("vh_"), k == 2 {
                        // discriminating rows: v0 and v1 disagree; vh must pick the right side
                        let v0 = e.demotion_v0["2"], v1 = e.demotion_v1["2"]
                        try expect(v0 != v1, "\(tag) v0 and v1 must disagree")
                        let wantV0 = c.name == "vh_short" || (c.name == "vh_boundary" && n != 1)
                        try expect(supported == (wantV0 ? v0 : v1), "\(tag) vh side (wantV0=\(wantV0))")
                    }
                }
            }
            let ks = HarmonicEpochClass.promotionKs(
                time: time, flux: flux, period: period, t0: t0, duration: duration,
                periodMax: 50, t0IsCentre: e.centre, excluded: ex
            )
            try expect(ks == e.ks, "\(tag) promotion ks \(ks) != \(e.ks)")
            let ksShort = HarmonicEpochClass.promotionKs(
                time: time, flux: flux, period: period, t0: t0, duration: duration,
                periodMax: dbl(e.period_max_short), t0IsCentre: e.centre, excluded: ex
            )
            try expect(ksShort == e.ks_short_max, "\(tag) promotion ks (period_max cut)")
        }
        for (n, s) in c.slots.enumerated() {
            let tag = "\(c.name) slot#\(n)"
            let accepted = s.accepted.map {
                EpochEphemeris(period: dbl($0.period), t0: dbl($0.t0), duration: dbl($0.duration))
            }
            let finite = time.filter(\.isFinite)
            let index = HarmonicEpochClass.findHarmonicEpochMatch(
                period: dbl(s.rm.period), t0: dbl(s.rm.t0), duration: dbl(s.rm.duration),
                accepted: accepted, tFirst: finite.first!, tLast: finite.last!,
                t0IsCentre: s.centre
            )
            try expect((index ?? -1) == s.match, "\(tag) match \(String(describing: index)) != \(s.match)")
            let drop = HarmonicEpochClass.slotDuplicate(
                time: time, flux: flux, slotPeriod: dbl(s.rm.period), slotT0: dbl(s.rm.t0),
                slotDuration: dbl(s.rm.duration), accepted: accepted, excluded: nil,
                t0IsCentre: s.centre
            )
            try expect(drop == s.drop, "\(tag) drop \(drop) != \(s.drop)")
        }
        for (n, p) in c.promotes.enumerated() {
            let tag = "\(c.name) promote#\(n)"
            let log = CallLog()
            let out = HarmonicEpochClass.promote(
                time: time, flux: flux, result: blsSeed(p.seed), periodMax: dbl(p.period_max),
                minimumSNR: dbl(p.snr_min), excluded: p.use_excluded ? excluded : nil,
                search: mockSearch(p.table, log)
            )
            try expect((out != nil) == p.promoted, "\(tag) promoted flag")
            try expect(sameResult(out ?? blsSeed(p.seed), p.result), "\(tag) result")
            try expect(log.calls == p.calls, "\(tag) BLS re-fit windows \(log.calls) != \(p.calls)")
        }
        for (n, r) in c.resolves.enumerated() {
            let tag = "\(c.name) resolve#\(n) (\(r.source))"
            let log = CallLog()
            let out = HarmonicResolver.resolve(
                time: time, flux: flux, seed: blsSeed(r.seed),
                periodMinimum: dbl(r.period_min), periodMaximum: dbl(r.period_max),
                options: HarmonicResolutionOptions(source: source(r.source), epochClass: true),
                excluded: r.use_excluded ? excluded : nil,
                search: mockSearch(r.table, log)
            )
            try expect(sameResult(out, r.result), "\(tag) result period \(out.period)")
            try expect(log.calls == r.calls, "\(tag) probe sequence")
        }
    }
}

/// Flag OFF must leave the resolver exactly as it was: (a) the six canned scenarios whose
/// expected values were captured from the pre-change Python resolver, with the default
/// options, an explicit `epochClass: false`, and an (ignored) exclusion mask; (b) real data
/// where the flag-ON result differs (promotion / veto) -> flag-OFF gives the old answer.
func testEpochClassFlagOffUnchanged() async throws {
    let fixture = try loadEpochFixture()
    try expect(HarmonicResolutionOptions().epochClass == false, "epoch class must default OFF")
    try expect(MultiPlanetOptions().harmonicEpochClass == false, "multi-planet flag must default OFF")
    let gt = (0..<fixture.flag_off_n).map { Double($0) * 0.1 }
    let gf = [Double](repeating: 1, count: gt.count)
    for r in fixture.flag_off {
        let name = r.name ?? "?"
        let masks: [[Bool]?] = [nil, [Bool](repeating: false, count: gt.count)]
        for mask in masks {
            let variants: [HarmonicResolutionOptions] = [
                HarmonicResolutionOptions(source: source(r.source)),
                HarmonicResolutionOptions(source: source(r.source), epochClass: false),
            ]
            for options in variants {
                let log = CallLog()
                let out = HarmonicResolver.resolve(
                    time: gt, flux: gf, seed: blsSeed(r.seed),
                    periodMinimum: dbl(r.period_min), periodMaximum: dbl(r.period_max),
                    options: options, excluded: mask, search: mockSearch(r.table, log)
                )
                try expect(same(out.period, r.result.period) && same(out.snr, r.result.snr)
                           && same(out.depth, r.result.depth),
                           "flag-off \(name) result \(out.period) \(out.snr) \(out.depth)")
                try expect(log.calls == r.calls, "flag-off \(name) probe sequence")
            }
        }
    }
    // Real data, flag OFF vs the flag-ON golden: the old behaviour must come back.
    guard let promotion = fixture.cases.first(where: { $0.name == "promotion" }) else {
        throw TestFailure(description: "promotion case missing")
    }
    let time = dbls(promotion.time), flux = dbls(promotion.flux)
    // resolve#0: SPOC, seed 6.235 (alias), 12.47 probe snr 50 < seed snr 200 -> old resolver
    // keeps the seed; ON promotes to 12.47.
    // resolve#2: seed 12.47 (true), /2 probe snr 300 -> old resolver demotes; ON vetoes.
    for (index, expectSeedKept) in [(0, true), (2, false)] {
        let r = promotion.resolves[index]
        let log = CallLog()
        let out = HarmonicResolver.resolve(
            time: time, flux: flux, seed: blsSeed(r.seed),
            periodMinimum: dbl(r.period_min), periodMaximum: dbl(r.period_max),
            options: HarmonicResolutionOptions(source: source(r.source), epochClass: false),
            excluded: [Bool](repeating: true, count: time.count),
            search: mockSearch(r.table, log)
        )
        if expectSeedKept {
            try expect(sameResult(out, r.seed), "flag-off must keep the alias seed")
        } else {
            try expect(same(out.period, r.table[0].period) && out.snr == dbl(r.table[0].snr),
                       "flag-off must take the (spurious) /2 demotion")
        }
        try expect(!sameResult(out, r.result), "flag-off result must differ from flag-on")
    }
}

func testEpochClassConfigPropagation() async throws {
    let defaults = PrimaryTaskProcessor.multiPlanetOptions(config: [:])
    try expect(!defaults.harmonicEpochClass, "harmonic_epoch_class must default to false")
    let on = PrimaryTaskProcessor.multiPlanetOptions(config: ["harmonic_epoch_class": .bool(true)])
    try expect(on.harmonicEpochClass, "harmonic_epoch_class=true must propagate")
    let off = PrimaryTaskProcessor.multiPlanetOptions(config: ["harmonic_epoch_class": .bool(false)])
    try expect(!off.harmonicEpochClass, "harmonic_epoch_class=false must propagate")
}
